function tabTo(selector: string, remaining = 40) {
  cy.document().then((document) => {
    if (document.activeElement?.matches(selector)) return;
    expect(remaining, `Tab reaches ${selector}`).to.be.greaterThan(0);
    pressKeyInChrome('Tab');
    tabTo(selector, remaining - 1);
  });
}
function assertUseCountLayout(scope: string) {
  cy.get(`${scope} dl`).should(($definitions) => {
    const counters = $definitions
      .toArray()
      .filter((definition) =>
        Array.from(definition.querySelectorAll('dt')).some(
          (term) => term.textContent?.trim() === 'Total',
        ),
      );
    expect(counters.length, 'Rendered use counters').to.be.greaterThan(0);
    for (const counter of counters) {
      const terms = Array.from(counter.querySelectorAll('dt'));
      expect(terms).to.have.length(4);
      for (const term of terms) {
        const value = term.nextElementSibling;
        expect(value?.tagName).to.equal('DD');
        // Grid-cell rectangles alone miss text overflowing its allocated
        // column. Ranges measure the rendered label and number themselves.
        const labelRange = term.ownerDocument.createRange();
        const valueRange = term.ownerDocument.createRange();
        labelRange.selectNodeContents(term);
        valueRange.selectNodeContents(value!);
        const labels = Array.from(labelRange.getClientRects());
        const values = Array.from(valueRange.getClientRects());
        expect(labels.length).to.be.greaterThan(0);
        expect(values.length).to.be.greaterThan(0);
        for (const label of labels)
          for (const number of values) {
            const horizontal =
              Math.min(label.right, number.right) -
              Math.max(label.left, number.left);
            const vertical =
              Math.min(label.bottom, number.bottom) -
              Math.max(label.top, number.top);
            expect(
              horizontal <= 0.5 || vertical <= 0.5,
              `${term.textContent} and ${value!.textContent} do not overlap`,
            ).to.equal(true);
          }
      }
    }
  });
}
function screenshot(name: string, width: number, height: number) {
  cy.document().should((document) => {
    // A native vertical scrollbar occupies layout pixels without changing
    // the viewport or PNG dimensions. Compare overflow against that layout.
    const availableWidth = document.documentElement.clientWidth;
    expect(availableWidth).to.be.greaterThan(0).and.at.most(width);
    expect(document.documentElement.scrollWidth).to.be.at.most(
      availableWidth + 1,
    );
  });
  cy.window().should((window) => {
    expect(window.innerWidth).to.equal(width);
    expect(window.innerHeight).to.equal(height);
  });
  cy.screenshot(name, { capture: 'viewport', overwrite: true });
}
function measure(c: Context, surface: 'list' | 'detail') {
  const draft: Measurement = {
    organizationId: c.organizationId,
    surface,
    firstNavigationMs: null,
    firstNavigationValid: false,
    samples: [],
    startedAt: null,
    index: 0,
  };
  cy.then(() => {
    measurement = draft;
  });
  for (let index = 0; index <= 50; index++) {
    cy.then(() => {
      draft.startedAt = performance.now();
      draft.index = index;
    });
    listReady(c);
    if (surface === 'detail') detailReady(c);
    cy.then(() => {
      const elapsed = performance.now() - draft.startedAt!;
      draft.startedAt = null;
      if (index === 0) {
        draft.firstNavigationMs = elapsed;
        draft.firstNavigationValid = true;
      } else draft.samples.push({ durationMs: elapsed, valid: true });
    });
  }
  cy.then(() =>
    cy.task<{ samples: number; p95Ms: number; passed: boolean }>(
      'bank:performance',
      draft,
      { log: false },
    ),
  ).then((result) => {
    expect(result.samples).to.equal(50);
    expect(result.p95Ms).to.be.lessThan(3000);
    expect(result.passed).to.equal(true);
    measurement = null;
  });
}

