      listReady(c);
      cy.wait('@bankList');
      targetRow(c)
        .should('contain.text', 'Profesor A')
        .and('contain.text', 'Versiones: 25');
      const seen: string[] = [];
      cy.get(rows).then(($rows) => {
        seen.push(
          ...$rows
            .toArray()
            .map((row) => row.getAttribute('data-exercise-id')!),
        );
      });
      pageNext('Páginas del banco');
      cy.wait('@bankList').then(({ request }) =>
        expect(new URL(request.url).searchParams.has('cursor')).to.equal(true),
      );
      cy.get(rows)
        .should('have.length', 5)
        .then(($rows) => {
          seen.push(
            ...$rows
              .toArray()
              .map((row) => row.getAttribute('data-exercise-id')!),
          );
          expect(new Set(seen).size).to.equal(25);
        });
      cy.get('[name="search"]').type('foco');
      cy.get('[name="state"]').select('ACTIVE');
      cy.get('[name="difficulty"]').select('BEGINNER');
      cy.get('[name="conceptId"]').select(c.conceptIds[0]!);
      cy.get('[name="visibility"]').select('ORGANIZATION');
      apply();
      cy.wait('@bankList').then(({ request, response }) => {
        expect(new URL(request.url).searchParams.has('cursor')).to.equal(false);
        expect(response!.body.data.page.totalFiltered).to.equal(1);
        expect(response!.body.data.items[0].id).to.equal(c.exerciseId);
      });
      cy.get(rows).should('have.length', 1);
      cy.get('[name="search"]').clear().type('sin coincidencias banco');
      apply();
      cy.contains('No hay ejercicios para estos filtros.').should('be.visible');
      cy.get(rows).should('not.exist');
      clearFilters();
      cy.get(rows).should('have.length', 20);
      cy.get('[name="state"]').select('ARCHIVED');
