  it('IMP06-BANK-05 · Respuesta tardía y caída real de API → no conserva datos obsoletos ni confunde fallo con vacío', () => {
    prepare().then((c) => {
      let held = false;
      let aborted: AbortSignal | null | undefined;
      visitAs(c.admin, route(c), (window) => {
        const original = window.fetch.bind(window);
        window.fetch = (input, init) =>
          original(input, init).then((response) => {
            if (
              !held &&
              String(input).includes('/exercise-bank?') &&
              String(input).includes('search=foco') &&
              response.ok
            ) {
              held = true;
              aborted = init?.signal;
              return new Promise<Response>((resolve) => {
                releaseResponse = () => resolve(response);
              });
            }
            return response;
          });
      });
      cy.get(rows).should('have.length', 20);
      cy.get('[name="search"]').type('foco');
      apply();
      cy.wrap(null).should(() => expect(releaseResponse).to.be.a('function'));
      cy.get(rows).should('not.exist');
      clearFilters();
      cy.get(rows).should('have.length', 20);
      cy.then(() => {
        expect(aborted?.aborted).to.equal(true);
        releaseResponse!();
      });
      cy.get(rows).should('have.length', 20);
      cy.task('foundation:apiStop', null, { log: false });
      cy.contains('button', 'Actualizar banco').click();
      cy.get('[role="alert"]').should('be.visible');
      cy.get(rows).should('not.exist');
      cy.contains('No hay ejercicios para estos filtros.').should('not.exist');
      cy.task('foundation:apiStart', null, { log: false });
      cy.contains('button', 'Actualizar banco').click();
      cy.get(rows).should('have.length', 20);
    });
  });

